require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_admin();$items=db()->query('SELECT l.*,u.name seller FROM listings l JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC')->fetchAll();$pageTitle='Listings';include dirname(__DIR__).'/includes/header.php';?><div class="section-head"><h2>Manage listings</h2></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Seller</th><th>Price</th><th>Status</th><th>Trust</th><th>Score</th></tr><?php foreach($items as $l):?><tr><td><a href="/listing.php?id=<?=$l['id']?>"><?=e($l['title'])?></a></td><td><?=e($l['seller'])?></td><td><?=money($l['price'])?></td><td><?=e($l['status'])?></td><td><?=e(trust_label($l['trust_status']??''))?></td><td><?=e((string)$l['fraud_score'])?></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>